import {auditEpisode,copyFor,timeRange} from './claim-firewall.js';
import {activeSources} from './reconstruction-core.js';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const list=items=>`<ul>${items.map(x=>`<li>${x}</li>`).join('')}</ul>`;
const refs=items=>list(items.map(e=>`<a href="#" data-source="${esc(e.sourceId)}">${esc(e.sourceId)} · v${e.sourceVersion}</a><blockquote>${esc(e.quote)}</blockquote>`));
export function renderFirewall(ledger,lang='en'){
 const c=copyFor(lang),a=auditEpisode(ledger,lang),zh=lang==='zh';
 const gaps=x=>x.coverage.gaps.map(w=>timeRange(w,lang));
 const coverage=x=>`<p>${esc(c.levels[x.coverage.level])} · ${esc(timeRange(x.claim.time,lang))}</p>${list(x.coverage.sources.map(s=>`${esc(s.label)} — ${esc(s.reasons.length?s.reasons.map(r=>c.reasons[r]).join('; '):c.reasons.declared_coverage)}`))}`;
 const sections=a.claims.map(x=>`<article class="fw-claim ${x.status.toLowerCase()}"><span class="fw-state">${esc(c.labels[x.status])}</span><p>${esc(x.wording)}</p><details><summary>${esc(c.audit)}</summary><h4>${esc(c.evidence)}</h4>${refs(x.supportingEvidence)}<h4>${esc(c.conflicts)}</h4>${x.contradictingEvidence.length?refs(x.contradictingEvidence):`<p>${esc(c.none)}</p>`}<h4>${esc(c.coverage)}</h4>${coverage(x)}<h4>${esc(c.blind)}</h4>${list([...gaps(x),...x.blindSpots].map(esc))}<h4>${esc(c.why)}</h4><p>${esc(x.reason)}</p>${list(x.alternatives.map(esc))}${x.unresolvedEvidence.length?refs(x.unresolvedEvidence):''}</details></article>`).join('');
 const rows=a.claims.map(x=>`<details class="fw-map-row"><summary>${esc(c.classes[x.claim.topic]||x.claim.topic)} — ${esc(c.levels[x.coverage.level])}<span class="fw-bar" aria-label="${esc(c.levels[x.coverage.level])}">${x.coverage.segments.length?x.coverage.segments.map(s=>`<span class="${s.sourceIds.length?'observed':'gap'}" style="flex:${Date.parse(s.end)-Date.parse(s.start)}" title="${esc(timeRange(s,lang))}"></span>`).join(''):'<span class="gap" style="flex:1"></span>'}</span></summary>${coverage(x)}${list(gaps(x).map(esc))}</details>`).join('');
 return `<section class="panel care-report firewall"><h2>${esc(c.title)}</h2><p>${esc(c.intro)}</p>${!['zh','en'].includes(lang)?`<p class="meta">${esc(c.fallback)}</p>`:''}${a.pendingSourceIds.length?`<p class="note">${zh?'还有新增或更正的原文尚未整理，本报告不完整。':'New or corrected accounts remain unanalysed; this report is incomplete.'}</p>`:''}${!a.claims.length?`<p>${esc(c.empty)}</p>`:sections}<p class="meta">${esc(c.draft)}</p></section>${a.claims.length?`<section class="panel"><h2>${esc(c.map)}</h2><p class="meta">${esc(c.unverified)}</p>${rows}</section>`:''}${a.timelines.length?`<section class="panel"><h2>${esc(c.alternate)}</h2>${a.timelines.map(group=>`${group.candidates.map((v,i)=>`<article class="fw-claim contested"><h3>${zh?'候选':'Candidate'} ${i+1}</h3>${refs(v.evidence)}<p>${esc(v.wording)}</p></article>`).join('')}<p>${esc(group.missing.join(' '))}</p>`).join('')}</section>`:''}${a.questions.length?`<section class="panel"><h2>${esc(c.debt)}</h2>${a.questions.map(q=>`<article><p><strong>${esc(q.text)}</strong></p><p class="meta">${esc(zh?'涉及记录':'Affects accounts')}: ${esc(q.affectedEvidence.join(', '))}</p><details><summary>${zh?'为什么先问这个？':'Why ask this first?'}</summary><p>${esc(q.reason)}</p><p>${zh?'排序分数（经验规则，不是概率）':'Heuristic priority, not probability'}: ${q.score}</p><p>${zh?'重要性 / 不确定性 / 可靠性缺口 / 预计澄清作用':'Importance / uncertainty / reliability gap / expected clarification'}: ${Object.values(q.factors).join(' / ')}</p></details></article>`).join('')}</section>`:''}`;
}
export function coverageEditor(ledger,lang='en'){
 const zh=lang==='zh',sources=activeSources(ledger);
 if(!sources.length)return '';
 const labels=zh?['补充观察范围','选择原始记录','实际观察对象（与提取结果中的对象一致）','确实能观察的事件','开始时间','结束时间','看不到的地方','保存观察范围','我已核对来源的实际能力；这不是让模型自行声明能力。','只记录自己确实知道的时段。缺失范围会保持未知。','移除观察设置','直接观察','间接信号','观察方式']:['Add observation coverage','Original account','Observed subject (same identity as extracted claims)','Events this source can actually observe','Start','End','Known blind spots','Save coverage','I reviewed this source’s actual capability; this is not a model declaration.','Only enter periods you actually know. Missing coverage remains unknown.','Remove observation setup','Direct observation','Indirect signal','Observation mode'];
 return `<section class="panel"><details><summary>${labels[0]}</summary><p>${labels[9]}</p><form id="coverage-form"><label>${labels[1]}<select name="source">${sources.map(s=>`<option value="${esc(s.id)}">${esc(s.author)} · ${esc(s.id)}</option>`).join('')}</select></label><label>${labels[2]}<input name="subject" required maxlength="80" placeholder="recipient"></label><label>${labels[3]}<select name="eventClass">${['medication','sleep','food','behavior','other'].map(k=>`<option value="${k}">${esc(copyFor(lang).classes[k])}</option>`).join('')}</select></label><label>${labels[13]}<select name="mode"><option value="direct">${labels[11]}</option><option value="indirect">${labels[12]}</option></select></label><label>${labels[4]}<input type="datetime-local" name="start" required></label><label>${labels[5]}<input type="datetime-local" name="end" required></label><label>${labels[6]}<input name="blind" maxlength="300"></label><label><input type="checkbox" name="reviewed" required>${labels[8]}</label><button type="submit">${labels[7]}</button></form>${(ledger.coverage?.profiles||[]).map(p=>`<article><p>${esc(p.label)} · ${esc(p.capabilities.map(k=>copyFor(lang).classes[k]||k).join(', '))}</p><button type="button" data-action="remove-coverage" data-id="${esc(p.id)}">${labels[10]}</button></article>`).join('')}</details></section>`;
}
